mapper.select:
SELECT c.*, u.nickname, u.avatar_url AS avatarUrl FROM comments c LEFT JOIN sys_user u ON c.user_id = u.id WHERE c.content_id = #{contentId}
AND c.episode_id = #{episodeId}
AND c.episode_id IS NULL
AND c.parent_id = 0 AND c.status = 1
ORDER BY c.like_count DESC, c.id DESC
ORDER BY c.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM comments WHERE content_id = #{contentId}
AND episode_id = #{episodeId}
AND episode_id IS NULL
AND parent_id = 0 AND status = 1

SELECT c.*, u.nickname, u.avatar_url AS avatarUrl, ru.nickname AS replyToNickname FROM comments c LEFT JOIN sys_user u ON c.user_id = u.id LEFT JOIN sys_user ru ON c.reply_to_user_id = ru.id WHERE c.root_id IN
#{id}
AND c.parent_id != 0 AND c.status = 1 ORDER BY c.created_at ASC
